package org.junit.java.util.json.output;

import java.util.ArrayList;

public class JsonOutput {
      private static ArrayList<Object> convertListToJsonArray(Object obj, String arrayListName) {
          ArrayList<Object> outputList = new ArrayList<Object>();
          try {
              outputList.add((String) obj);
              return outputList;
          } catch (Exception ex) {
              throw new RuntimeException( ex );
          }
      }

